t.N("באיזה גיל (חודשים) מצופים צירופי 2 מילים?", 24, 0, "חודשים")
t.M("ילד מעתיק צלב אבל לא משולש. מה גילו ההתפתחותי?", ["2 שנים", "3 שנים", "4 שנים", "6 שנים"], 2, "עיגול 3, צלב 4, ריבוע 4-5, משולש 5.")
t.F("מדוע העדפת יד לפני גיל 18 חודשים מדאיגה?", "עלולה להעיד על חולשה בצד הנגדי, למשל המיפלגיה (CP).")
t.N("עד איזה גיל (חודשים) רפלקס Moro צריך להיעלם? (ערך עליון)", 6, 0, "חודשים")
t.F("מנה 4 דגלים אדומים בהתפתחות השפה והתקשורת.", "אין מלמול או הצבעה ב-12 חודשים, אין מילים בודדות ב-16 חודשים, אין צירופי 2 מילים ספונטניים ב-24 חודשים, כל רגרסיה בשפה או בכישורים חברתיים בכל גיל.")
T.append(t)

t = Topic("bron", "ברונכיוליטיס", "Bronchiolitis", "נשימה ילדים", SRC, """
<h4>רקע</h4><ul><li>תינוקות מתחת לגיל שנתיים, שיא 2-6 חודשים. חורף.</li><li>RSV הוא המחולל השכיח ביותר (גם: rhinovirus, hMPV, parainfluenza, adenovirus).</li><li>אבחנה קלינית: נזלת שמתקדמת תוך 2-3 ימים לשיעול, טכיפנאה, צפצופים וחרחורים.</li></ul>
<h4>גורמי סיכון למחלה קשה</h4><ul><li>פגות (פחות מ-35 שבועות), גיל מתחת ל-12 שבועות, מחלת לב מולדת המודינמית, מחלת ריאות כרונית (BPD), חסר חיסוני, מחלה נוירומוסקולרית.</li></ul>
<h4>טיפול (AAP)</h4><ul><li>תמיכתי: סקשן, נוזלים, חמצן אם סטורציה מתחת ל-90%.</li><li>לא מומלצים: ברונכודילטורים, סטרואידים, אנטיביוטיקה, אפינפרין שגרתי, פיזיותרפיה נשימתית, צילום חזה שגרתי.</li><li>מי מלח היפרטוניים: אפשרי במאושפזים.</li><li>HFNC: לכשל נשימתי מתפתח.</li></ul>
<h4>מניעה</h4><ul><li>Nirsevimab (נוגדן חד-שבטי ארוך טווח) לכל התינוקות בעונה הראשונה, או חיסון RSV לאם בשבועות 32-36 להריון. Palivizumab חודשי לקבוצות סיכון.</li></ul>
<h4>סיבוכים</h4><ul><li>דום נשימה (בעיקר פגים ומתחת לחודשיים), כשל נשימתי, דלקת אוזניים, קשר לצפצופים חוזרים ואסתמה.</li></ul>
""", ["RSV", "bronchiolitis"])
t.M("מהו המחולל השכיח ביותר של ברונכיוליטיס?", ["Rhinovirus", "RSV", "Parainfluenza", "Adenovirus"], 1)
